def error_class_for(code: str, status_code: Optional[int]) -> Type[AlterLabAPIError]:
    """Typed error class for a code, falling back to the status class."""
    found = ERROR_CLASSES.get(code)
    if found is not None:
        return found
    return ClientError if (status_code or 500) < 500 else ServerError


def error_for_response(
    status_code: int, detail: Any, response: Optional[httpx.Response] = None
) -> AlterLabAPIError:
    """Build the typed error for a failed HTTP response."""
    fields = typed_fields(status_code, response)
    return error_class_for(fields["code"], status_code)(status_code, detail, response)


